export function encodeBase64(r){if(Uint8Array.prototype.toBase64)return r.toBase64();const t=[];for(let e=0;e<r.length;e+=32768)t.push(String.fromCharCode.apply(null,r.subarray(e,e+32768)));return btoa(t.join(""))}export function decodeBase64(r){if(Uint8Array.fromBase64)return Uint8Array.fromBase64(r);const t=atob(r),e=new Uint8Array(t.length);for(let r=0;r<t.length;r++)e[r]=t.charCodeAt(r);return e}